messages = []


def is_night_shift(shift_doc):
    return frappe.utils.get_time(shift_doc.end_time) <= frappe.utils.get_time(shift_doc.start_time)


def get_shift_window(shift, ref_date):
    shift_start = frappe.utils.get_datetime(
        f"{ref_date} {frappe.utils.get_time(shift.start_time)}"
    )
    shift_end = frappe.utils.get_datetime(
        f"{ref_date} {frappe.utils.get_time(shift.end_time)}"
    )

    if shift_end <= shift_start:
        shift_end = frappe.utils.add_to_date(shift_end, days=1, as_datetime=True)

    actual_start = frappe.utils.add_to_date(
        shift_start,
        minutes=-(shift.begin_check_in_before_shift_start_time or 0),
        as_datetime=True
    )
    actual_end = frappe.utils.add_to_date(
        shift_end,
        minutes=(shift.allow_check_out_after_shift_end_time or 0),
        as_datetime=True
    )

    return {
        "shift_start": shift_start,
        "shift_end": shift_end,
        "actual_start": actual_start,
        "actual_end": actual_end,
    }


def get_next_shift(employee_name, current_shift):
    assignments = frappe.get_all(
        "Shift Assignment",
        filters={"employee": employee_name, "docstatus": 1},
        fields=["shift_type"]
    )
    assigned_names = {d.shift_type for d in assignments}

    shifts = frappe.get_all(
        "Shift Type",
        fields=["name", "start_time"],
        order_by="start_time asc"
    )

    all_names = [d.name for d in shifts]

    if current_shift.name not in all_names:
        return None

    current_idx = all_names.index(current_shift.name)

    for i in range(1, len(shifts) + 1):
        next_idx = (current_idx + i) % len(shifts)
        if shifts[next_idx].name in assigned_names:
            return frappe.get_doc("Shift Type", shifts[next_idx].name)

    return None


def detect_shift(emp, punch_time, previous_shift=None, log_type=None):
    if previous_shift and log_type == "OUT":
        shift_doc = frappe.get_doc("Shift Type", previous_shift)
        night = is_night_shift(shift_doc)

        for offset in [0, -1] if night else [0]:
            ref_date = frappe.utils.add_to_date(punch_time.date(), days=offset)
            window = get_shift_window(shift_doc, ref_date)

            half_day_threshold = shift_doc.working_hours_threshold_for_half_day or 4
            buffer_end = frappe.utils.add_to_date(
                window["actual_end"], hours=half_day_threshold, as_datetime=True
            )

            if window["actual_start"] <= punch_time <= buffer_end:
                return {"shift": shift_doc, "window": window}

    if previous_shift:
        shift_doc = frappe.get_doc("Shift Type", previous_shift)
        night = is_night_shift(shift_doc)

        for offset in [0, -1] if night else [0]:
            ref_date = frappe.utils.add_to_date(punch_time.date(), days=offset)
            window = get_shift_window(shift_doc, ref_date)

            if window["actual_start"] <= punch_time <= window["actual_end"]:
                return {"shift": shift_doc, "window": window}

    assignments = frappe.get_all(
        "Shift Assignment",
        filters={"employee": emp, "docstatus": 1},
        fields=["shift_type", "start_date", "end_date"]
    )
    candidates = []

    for assignment in assignments:
        if assignment.start_date and punch_time.date() < assignment.start_date:
            continue
        if assignment.end_date and punch_time.date() > assignment.end_date:
            continue

        shift = frappe.get_doc("Shift Type", assignment.shift_type)

        if shift_type and shift.name != shift_type:
            continue

        night = is_night_shift(shift)

        for offset in [0, -1] if night else [0]:
            ref_date = frappe.utils.add_to_date(punch_time.date(), days=offset)
            window = get_shift_window(shift, ref_date)

            if window["actual_start"] <= punch_time <= window["actual_end"]:
                diff = abs((punch_time - window["actual_start"]).total_seconds())
                candidates.append({"shift": shift, "window": window, "diff": diff})

    if not candidates:
        return None

    candidates.sort(key=lambda x: x["diff"])
    return candidates[0]


employee_logs = {}
last_shift_by_employee = {}

for log in logs:
    punch_time = frappe.utils.get_datetime(log.time)
    previous_shift = last_shift_by_employee.get(log.employee)

    detected = detect_shift(log.employee, punch_time, previous_shift, log.log_type)

    if not detected:
        if log.log_type == "OUT" and previous_shift:
            detected = {"shift": frappe.get_doc("Shift Type", previous_shift), "window": None}
            messages.append(
                f"{log.employee}: {log.name} fallback assigned to {previous_shift}"
            )
        else:
            messages.append(
                f"{log.employee}: {log.name} could not be assigned, skipped"
            )
            continue

    detected_shift_name = detected["shift"].name

    if log.shift != detected_shift_name:
        frappe.db.set_value("Employee Checkin", log.name, "shift", detected_shift_name)
        messages.append(
            f"{log.employee}: {log.name} {log.shift or 'None'} \u2192 {detected_shift_name}"
        )

    last_shift_by_employee[log.employee] = detected_shift_name

    employee_logs.setdefault(log.employee, []).append({
        "log": log,
        "detected": detected,
        "punch_time": punch_time,
    })


for emp, emp_logs in employee_logs.items():
    if len(emp_logs) < 2:
        continue

    for i in range(len(emp_logs) - 1):
        current = emp_logs[i]
        nxt = emp_logs[i + 1]

        current_shift = current["detected"]["shift"]
        current_window = current["detected"].get("window")
        if not current_window:
            continue

        nxt_shift = nxt["detected"]["shift"]

        if current_shift.name == nxt_shift.name:
            continue

        actual_end = current_window["actual_end"]
        nxt_time = nxt["punch_time"]

        if nxt_time <= actual_end:
            continue

        next_shift_hours = frappe.utils.time_diff_in_hours(nxt_time, actual_end)
        threshold = current_shift.working_hours_threshold_for_half_day or 4

        if next_shift_hours < threshold:
            nxt_shift_name = nxt_shift.name
            nxt_log_name = nxt["log"].name
            nxt_original_shift = nxt["log"].shift
            if nxt_original_shift != current_shift.name:
                frappe.db.set_value("Employee Checkin", nxt_log_name, "shift", current_shift.name)
                messages.append(
                    f"{emp}: {nxt_log_name} {nxt_original_shift or 'None'} \u2192 {current_shift.name} (below threshold)"
                )
                last_shift_by_employee[emp] = current_shift.name
                nxt["detected"]["shift"] = current_shift
                nxt["detected"]["window"] = current_window
            continue

        next_shift = get_next_shift(emp, current_shift)
        if not next_shift:
            continue

        from datetime import timedelta

        boundary_time = actual_end
        tolerance = timedelta(minutes=1)

        out_exists = frappe.db.exists("Employee Checkin", {
            "employee": emp,
            "time": ["between", [boundary_time - tolerance, boundary_time + tolerance]],
            "shift": current_shift.name,
            "log_type": "OUT",
        })

        if not out_exists:
            frappe.get_doc({
                "doctype": "Employee Checkin",
                "employee": emp,
                "time": boundary_time,
                "shift": current_shift.name,
                "log_type": "OUT",
                "skip_auto_attendance": 0,
            }).insert(ignore_permissions=True)
            messages.append(f"{emp}: boundary OUT created for {current_shift.name}")

        in_exists = frappe.db.exists("Employee Checkin", {
            "employee": emp,
            "time": ["between", [boundary_time - tolerance, boundary_time + tolerance]],
            "shift": next_shift.name,
            "log_type": "IN",
        })

        if not in_exists:
            frappe.get_doc({
                "doctype": "Employee Checkin",
                "employee": emp,
                "time": boundary_time,
                "shift": next_shift.name,
                "log_type": "IN",
                "skip_auto_attendance": 0,
            }).insert(ignore_permissions=True)
            messages.append(f"{emp}: boundary IN created for {next_shift.name}")

frappe.db.commit()

frappe.response["message"] = messages if messages else "No changes required"

DOCUMENT_TYPES = {
    "AADHAAR_CARD": "Aadhaar Card",
    "PAN_CARD": "PAN Card",
    "RESUME": "Resume",
    "EDUCATION_CERTIFICATE": "Education Certificate",
    "EXPERIENCE_LETTER": "Experience Letter",
    "ADDRESS_PROOF": "Address Proof",
    "BANK_PROOF": "Bank Proof",
    "OTHER": "Other"
}


def check_employee(employee):

    if not employee:
        frappe.throw("Employee is required")

    if not frappe.db.exists("Employee", employee):
        frappe.throw(
            "Employee " + str(employee) + " does not exist"
        )


def get_document_type_from_filename(file_name):

    if not file_name:
        return None

    for key in DOCUMENT_TYPES:

        prefix = "[" + key + "]"

        if file_name.startswith(prefix):

            return {
                "key": key,
                "label": DOCUMENT_TYPES[key]
            }

    return None


action = frappe.form_dict.get("action")
employee = frappe.form_dict.get("employee")


# ============================================================
# LIST
# ============================================================

if action == "list":

    check_employee(employee)

    files = frappe.get_all(
        "File",
        filters={
            "attached_to_doctype": "Employee",
            "attached_to_name": employee
        },
        fields=[
            "name",
            "file_name",
            "file_url",
            "is_private",
            "creation"
        ],
        order_by="creation desc"
    )

    result = []

    for file in files:

        document = get_document_type_from_filename(
            file.file_name
        )

        if not document:
            continue

        result.append({
            "name": file.name,
            "document_type": document["key"],
            "document_label": document["label"],
            "file_name": file.file_name,
            "file_url": file.file_url,
            "is_private": file.is_private,
            "creation": file.creation
        })

    frappe.response["message"] = result


# ============================================================
# DELETE
# ============================================================

elif action == "delete":

    check_employee(employee)

    file_name = frappe.form_dict.get(
        "file_name"
    )

    if not file_name:
        frappe.throw(
            "File name is required"
        )


    file_doc = frappe.get_doc(
        "File",
        file_name
    )


    if (
        file_doc.attached_to_doctype
        != "Employee"
    ):
        frappe.throw(
            "Invalid Employee file"
        )


    if (
        file_doc.attached_to_name
        != employee
    ):
        frappe.throw(
            "This file does not belong to this Employee"
        )


    document = (
        get_document_type_from_filename(
            file_doc.file_name
        )
    )

    if not document:
        frappe.throw(
            "This file is not an Employee document"
        )


    frappe.delete_doc(
        "File",
        file_name,
        ignore_permissions=True
    )


    frappe.response["message"] = {
        "success": True
    }


else:

    frappe.throw(
        "Invalid action. Use list or delete."
    )
